INSERT INTO guides (slug,title,excerpt,cover,duration,difficulty,tools,blocks,sort_order,is_active) VALUES
('ustanovka-ramki-hyundai-solaris','Установка переходной рамки в Hyundai Solaris',
 'Пошагово: снимаем накладку консоли, подгоняем рамку и ставим магнитолу 2DIN. Без пропилов и подрезки штатного пластика.',
 'https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/4b88cf74-eefc-4005-acba-8ff11940ced1.jpg',
 '40 минут','просто',
 '["Пластиковые лопатки","Крестовая отвёртка","Ключ на 10"]'::jsonb,
 '[{"type":"text","text":"Рамка ставится в штатное место без доработок. Главное — аккуратно снять накладку центральной консоли: она держится на защёлках, которые легко сломать при спешке."},
   {"type":"step","title":"Обесточить машину","text":"Снимите минусовую клемму с аккумулятора и подождите 5 минут. Рядом проходит шлейф подушки безопасности.","image":"https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/b7c028dd-fbe0-42f5-a816-cdcd82aed018.jpg"},
   {"type":"step","title":"Снять накладку консоли","text":"Подденьте лопаткой снизу по центру и ведите вверх по кругу. Шесть защёлок, саморезов нет."},
   {"type":"step","title":"Извлечь штатную магнитолу","text":"Четыре болта на 10 по углам. Отсоедините разъём питания и антенну, нажав на фиксатор."},
   {"type":"step","title":"Установить рамку","text":"Вставьте рамку в проём и закрепите штатными саморезами. Не перетягивайте: пластик даст трещину.","image":"https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/b7c028dd-fbe0-42f5-a816-cdcd82aed018.jpg"},
   {"type":"note","text":"Перед сборкой проверьте зазор между магнитолой и кнопками аварийки — не меньше 2 мм, иначе кнопки будут заедать."},
   {"type":"step","title":"Собрать обратно","text":"Защёлкните накладку, подключите клемму и проверьте звук, экран и кнопки на руле."}]'::jsonb,
 10,TRUE),
('ustanovka-ramki-kia-rio','Установка рамки 10 дюймов в Kia Rio',
 'Что делать с воздуховодом, который упирается в корпус магнитолы, и как закрепить рамку без люфта.',
 'https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/4b88cf74-eefc-4005-acba-8ff11940ced1.jpg',
 '1 час','средне',
 '["Пластиковые лопатки","Отвёртка Torx","Кусачки","Фен"]'::jsonb,
 '[{"type":"text","text":"Под экран 10 дюймов места в штатном проёме не хватает: мешает воздуховод центрального дефлектора. Его нужно отогнуть — это обратимо и на работу климата не влияет."},
   {"type":"step","title":"Снять центральную консоль","text":"Начните снизу, от блока климата. Восемь защёлок по периметру.","image":"https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/b7c028dd-fbe0-42f5-a816-cdcd82aed018.jpg"},
   {"type":"step","title":"Отогнуть воздуховод","text":"Открутите два самореза сверху, сдвиньте патрубок влево. Если мешает — прогрейте феном и аккуратно отформуйте."},
   {"type":"note","text":"Не грейте пластик выше 60 градусов: побелеет и потеряет форму. Фен держите на расстоянии 15 см."},
   {"type":"step","title":"Примерить магнитолу","text":"Вставьте магнитолу в рамку и проверьте, что экран не задевает дефлекторы при повороте жалюзи.","image":"https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/b7c028dd-fbe0-42f5-a816-cdcd82aed018.jpg"},
   {"type":"step","title":"Зафиксировать рамку","text":"Штатные точки крепления совпадают. Затяните четыре самореза крест-накрест."}]'::jsonb,
 20,TRUE),
('ustanovka-ramki-lada-vesta','Установка рамки 2DIN в Lada Vesta',
 'Самый простой случай: рамка встаёт по штатным точкам, переносим только кнопку аварийки.',
 'https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/4b88cf74-eefc-4005-acba-8ff11940ced1.jpg',
 '30 минут','просто',
 '["Пластиковая лопатка","Крестовая отвёртка"]'::jsonb,
 '[{"type":"text","text":"На Весте проём под магнитолу почти совпадает с 2DIN, поэтому установка занимает полчаса. Единственная особенность — кнопка аварийной сигнализации переезжает в новую рамку."},
   {"type":"step","title":"Снять облицовку","text":"Подденьте лопаткой справа, затем слева. Держится на четырёх защёлках.","image":"https://cdn.poehali.dev/projects/e02f6838-189a-4b34-9b79-263263819d03/files/b7c028dd-fbe0-42f5-a816-cdcd82aed018.jpg"},
   {"type":"step","title":"Переставить кнопку аварийки","text":"Выдавите кнопку изнутри и защёлкните в посадочное место рамки. Разъём тот же, удлинитель не нужен."},
   {"type":"note","text":"Ставьте рамку в тёплом помещении: на морозе ABS-пластик становится хрупким и защёлки скалываются."},
   {"type":"step","title":"Установить магнитолу","text":"Закрепите магнитолу в рамке, подключите жгут ISO и антенну, поставьте узел на место."}]'::jsonb,
 30,TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO product_guides (product_id, guide_id)
SELECT p.id, g.id FROM products p JOIN guides g ON TRUE
WHERE (g.slug='ustanovka-ramki-hyundai-solaris' AND p.slug IN ('ramka-hyundai-solaris-2din','ramka-hyundai-creta-9'))
   OR (g.slug='ustanovka-ramki-kia-rio' AND p.slug IN ('ramka-kia-rio-10','ramka-kia-sportage-9'))
   OR (g.slug='ustanovka-ramki-lada-vesta' AND p.slug IN ('ramka-lada-vesta-2din','ramka-lada-granta-9'))
ON CONFLICT DO NOTHING;